def format_prompt(user_query: str, system_context: str = "You are a helpful AI Engineering tutor.") -> dict:
    return {
        "system": system_context,
        "user": user_query.strip()
    }

payload = format_prompt("How does self-attention work in Transformers?")
print(payload)

class LLMClient:
    def __init__(self, api_key: str, model: str = 'gemini-3.5-flash'):
        self.api_key = api_key
        self.model = model

    def generate(self, prompt: str) -> str:
        return f"[Response from {self.model} for: '{prompt}']"

client = LLMClient(api_key='sk-test-123')
print(client.generate('Explain gradient descent'))
